                  <option value="Sim">Sim</option>
                  <option value="Não">Não</option>
                </select>
              </th>
            </tr>
          </thead>
          <tbody>
            {empresasVisiveis.map(emp => (
              <tr key={emp.cod_folha || emp.id}>
                <td><input type="checkbox" checked={emp.selecionado || false} onChange={() => toggleSelecionado(emp)} /></td>
                <td onClick={() => abrirModal(emp)} style={{ cursor: 'pointer', color: '#2B9FAE', fontWeight: 'bold' }}>{emp.cod_folha}</td>
                <td>{emp.razao_social}</td>
                <td>{emp.grupo_economico}</td>
                <td>{emp.cnpj_formatado}</td>
                <td>{emp.status_do_cliente}</td>
                <td>{emp.inicio_contrato}</td>
                <td>{emp.termino_contrato}</td>
                <td>{emp.tributacao}</td>
                <td>{emp.sistema}</td>
                <td>{emp.grupo}</td>
                <td>{emp.resp_dp}</td>
                {/* <td>{emp.ramal}</td> */}
                <td>{emp.data_pagto_salario}</td>
                <td>{emp.classificacao}</td>
                <td>{emp.classificacao2}</td>
                <td>{emp.matriz}</td>
                <td>{emp.enviadctf}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Paginação e modais permanecem iguais */}
    </div>
  );
}
